package app.cloudbase.core

import kotlin.math.floor
import kotlin.math.min

/**
 * Coarse EGM96 geoid model. The grid is a classpath resource generated by `tools/make_geoid.py`
 * from the real NGA 15' EGM96 grid: 1 degree spacing, whole metres, signed bytes, 181 latitude rows
 * (south to north, -90..+90) by 360 longitude columns (-180..+179, wrapping), 65160 bytes.
 *
 * Error against the full 15' grid over New Zealand: median 0.3 m, 95 % within 1 m, worst 2.6 m.
 * Worse over the very steepest geoid features elsewhere (see GeoidTest). This is a fallback for
 * when neither Android nor the GPS chipset reports a geoid height; it is not survey grade.
 */
object Geoid {
    private const val STEP_DEG = 1.0
    private const val ROWS = 181
    private const val COLS = 360
    private const val RESOURCE = "/app/cloudbase/core/egm96_1deg.s8"

    private val grid: ByteArray by lazy { load() }

    /**
     * EGM96 geoid height above the WGS84 ellipsoid, metres. MSL altitude = ellipsoid altitude − this.
     * Bilinear interpolation; longitude wraps, latitude beyond the poles is clamped. NaN in, NaN out.
     */
    fun height(lat: Double, lon: Double): Double {
        if (!lat.isFinite() || !lon.isFinite()) return Double.NaN
        val g = grid
        val y = (lat.coerceIn(-90.0, 90.0) + 90.0) / STEP_DEG // 0..180
        var x = (lon + 180.0) / STEP_DEG
        x -= floor(x / COLS) * COLS // 0..360
        if (x >= COLS) x -= COLS // rounding can land exactly on COLS
        val i = min(y.toInt(), ROWS - 2)
        val j = x.toInt()
        val fy = y - i
        val fx = x - j
        val j1 = if (j + 1 == COLS) 0 else j + 1
        val south = g[i * COLS + j] * (1.0 - fx) + g[i * COLS + j1] * fx
        val north = g[(i + 1) * COLS + j] * (1.0 - fx) + g[(i + 1) * COLS + j1] * fx
        return south * (1.0 - fy) + north * fy
    }

    private fun load(): ByteArray {
        val bytes = Geoid::class.java.getResourceAsStream(RESOURCE)?.use { it.readBytes() }
            ?: throw IllegalStateException("missing resource $RESOURCE")
        check(bytes.size == ROWS * COLS) { "bad geoid grid size ${bytes.size}" }
        return bytes
    }
}
